 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\">Du kh\u00e1ch khi gh\u00e9 th\u0103m \u0111\u1ec1n M\u1eabu \u00c2u C\u01a1 th\u01b0\u1eddng d\u1eebng l\u1ea1i tr\u01b0\u1edbc ao sen \u0111\u1ec3 check in ch\u1ee5p \u1ea3nh. \u0110\u1ebfn m\u00f9a sen t\u1eebng \u0111\u00f3a hoa m\u1ecdc san s\u00e1t nhau, thi nhau khoe s\u1eafc t\u1ecfa h\u01b0\u01a1ng. M\u00f9i h\u01b0\u01a1ng sen d\u1ec5 ch\u1ecbu t\u01b0\u01a1i m\u00e1t l\u00e0m t\u0103ng th\u00eam v\u1ebb linh thi\u00eang cho ng\u00f4i \u0111\u1ec1n.</SPAN></DIV></div>",
