 "scrollBarVisible": "rollOver",
 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\">\u200b\u0110\u00e2y l\u00e0 n\u01a1i M\u1eabu M\u1eb9 \u00c2u C\u01a1 c\u00f9ng con c\u00e1i sinh ho\u1ea1t h\u00e0ng ng\u00e0y, v\u00e0 c\u0169ng l\u00e0 n\u01a1i M\u1eabu M\u1eb9 \u00c2u C\u01a1 soi g\u01b0\u01a1ng tr\u1ea3i t\u00f3c v\u00e0o l\u00fac tr\u0103ng thanh gi\u00f3 m\u00e1t.</SPAN></DIV><p STYLE=\"margin:0; line-height:12px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\">Th\u00e1ng 8 n\u0103m 2003, gia \u0111\u00ecnh \u00f4ng b\u00e0 L\u00ea V\u0103n L\u1eadp - Ng\u00f4 Th\u1ecb Nh\u00e0ng v\u00e0 c\u00e1c con \u1ee7ng h\u1ed9 x\u00e2y d\u1ef1ng l\u1ea1i gi\u1ebfng Ph\u01b0\u1ee3ng tr\u00ean n\u1ec1n gi\u1ebfng c\u0169.</SPAN></DIV><p STYLE=\"margin:0; line-height:12px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:12px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:12px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p></div>",
