 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0px;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:15px;\"> \u2022 D\u01b0\u1edbi g\u1ed1c \u0111a l\u00e0 Mi\u1ebfu C\u00f4: Th\u1edd \u0110\u1ec7 nh\u1ea5t v\u01b0\u01a1ng c\u00f4 v\u00e0 \u0110\u1ec7 nh\u1ecb v\u01b0\u01a1ng c\u00f4. T\u01b0\u01a1ng truy\u1ec1n r\u1eb1ng \u0110\u1ec7 nh\u1ea5t v\u01b0\u01a1ng c\u00f4 v\u00e0 \u0110\u1ec7 nh\u1ecb v\u01b0\u01a1ng c\u00f4 l\u00e0 ng\u01b0\u1eddi lu\u00f4n h\u1ea7u c\u1eadn b\u00ean m\u1eabu m\u1eb9 \u00c2u c\u01a1.</SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:15px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:15px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:15px;\"><BR STYLE=\"letter-spacing:0px;color:#000000;font-size:12px;font-family:Arial, Helvetica, sans-serif;\"/></p></div>",
